constraints:
2 <= N <= 10^{9}

expected time complexity: O(sqrt(N))
expected auxiliary space: O(1)

standard_solution_code:
class Solution:

	def isprime(self, n):
		if n == 1:
			return False
		for i in range(2, int(n ** 0.5) + 1):
			if n % i == 0:
				return False
		return True

	def largestPrimeFactor(self, N):
		for i in range(N, 1, -1):
			if N % i == 0 and self.isprime(i):
				return i
				break
